questions.question:
What does this program print? (std::println prints a vector of double as [a, b, c], and 6.0 as 6.)

#include <print>
#include <vector>

void bump(double s) { s += 1.0; }
void bump_ref(double& s) { s += 1.0; }

int main() {
    std::vector<double> v{5.0, 6.0, 7.0};
    for (auto s : v) s += 1.0;
    bump(v[0]);
    bump_ref(v[1]);
    auto x = v[2];
    x += 1.0;
    auto& y = v[2];
    y += 0.5;
    std::println("{}", v);
}

